warp:
shader_body
{
vec2 _uv = uv;


    vec2 d = 0.02*aspect.zw;
    vec3 dx = ( ((texture(sampler_blur2, _uv+vec2(1.0,0.0)*d-floor(_uv+vec2(1.0,0.0)*d)).xyz * scale2) + bias2)-((texture(sampler_blur2, _uv-vec2(1.0,0.0)*d-floor(_uv-vec2(1.0,0.0)*d)).xyz * scale2) + bias2) );
    vec3 dy = ( ((texture(sampler_blur2, _uv+vec2(0.0,1.0)*d-floor(_uv+vec2(0.0,1.0)*d)).xyz * scale2) + bias2)-((texture(sampler_blur2, _uv-vec2(0.0,1.0)*d-floor(_uv-vec2(0.0,1.0)*d)).xyz * scale2) + bias2) );
    vec3 b1 = ((texture(sampler_blur1, _uv).xyz * scale1) + bias1) - 0.0;
    d = vec2(0.01);
    float d2 = -0.02;
    float thr = 0.0;
    float c = 0.005;


    vec2 my_uv = _uv - vec2(dx.y,dy.y)*d - vec2(dy.x,-dx.x)*d2;
    ret.y = texture( sampler_fc_main, my_uv-floor(my_uv)).y;
    ret.y += (ret.y - b1.y - thr)*.02 +c;


    my_uv = _uv - vec2(dx.x,dy.x)*d - vec2(dy.z,-dx.z)*d2;
    ret.x = texture( sampler_fc_main, my_uv-floor(my_uv)).x;
    ret.x += (ret.x - b1.x - thr)*.02 +c;


    my_uv = _uv - vec2(dx.z,dy.z)*d - vec2(dy.y,-dx.y)*d2;
    ret.z = texture( sampler_fc_main, my_uv-floor(my_uv)).z;
    ret.z += (ret.z - b1.z - thr)*.02 +c;



}

comp:
shader_body
{
    float rad_lq = rad * length(texsize.xy)*0.5;
    float ang_lq = ang;
    vec2 uv_temp1 = (uv - 0.5) * texsize.xy;
    float rad_hq = length(uv_temp1);
    float ang_hq = atan(-uv_temp1.y, uv_temp1.x);

    vec2 uv2 = vec2((uv - 0.5));
    float rad2 = rad_lq*0.75;
    float ang2 = ang_lq * M_INV_PI_2;

        // ROTATION OVER TIME
        ang2 += time*0.025;   //rotate over time

        // FIN TYPE
        float fins = 8.0;//3.0 + floor(rand_preset.z*5.95);
        ang2 = cos(ang2*M_PI_2*fins) * 0.023;


    ang2 *= M_PI_2;
    uv2 = 0.5 + rad2*vec2(cos(ang2),sin(ang2))*texsize.zw;

